q(1,"Se o réu se livrar solto, deverá ser posto em liberdade",["depois de lavrado o auto de prisão em flagrante.","antes de lavrado o auto.","após a sentença.","apenas depois de 48 horas.","por ordem do promotor."],"Art. 309.")
q(1,"Após receber o auto de prisão em flagrante, no prazo máximo de 24 horas após a prisão, o juiz deverá promover",["audiência de custódia.","o julgamento do réu.","a oitiva das testemunhas.","o arquivamento.","a denúncia."],"Art. 310, caput.")
q(1,"No texto do assalto, os guardas perseguiram o homem sem perdê-lo de vista. A situação enquadra-se em",["flagrante impróprio, do art. 302, III.","flagrante próprio, do art. 302, I.","flagrante presumido, do art. 302, IV.","prisão preventiva.","prisão temporária."],"Perseguição logo após o crime: art. 302, III.","cpp2a")
q(1,"No texto do assalto, a primeira pessoa ouvida pela autoridade foi o",["guarda condutor, como determina o art. 304.","preso.","testemunha.","vítima.","promotor."],"Art. 304, caput.","cpp2a")
# n=2
q(2,"Do auto de prisão em flagrante deverá constar a informação sobre",["a existência de filhos da pessoa presa, suas idades e se possuem deficiência.","o patrimônio do preso.","a religião do preso.","as dívidas do preso.","os crimes de seus parentes."],"Art. 304, § 4º.")
q(2,"No flagrante, a comunicação da prisão e do local onde o preso se encontra deve ser feita, imediatamente, a",["juiz, Ministério Público e família do preso ou pessoa por ele indicada.","juiz e Defensoria Pública, apenas.","delegado-geral e imprensa.","promotor e vítima.","juiz e vítima."],"Art. 306, caput.")
q(2,"Se o autuado não informar o nome de seu advogado, o auto será encaminhado ao juiz, e cópia integral irá",["à Defensoria Pública.","ao Ministério Público.","à vítima.","ao delegado-geral.","à OAB."],"Art. 306, § 1º.")
q(2,"Quando o fato for praticado em presença da autoridade, constarão do auto, entre outros, a narração do fato e",["a voz de prisão e as declarações do preso e depoimentos das testemunhas.","somente o nome do preso.","apenas o laudo.","apenas o depoimento da vítima.","somente a sentença."],"Art. 307.")
q(2,"Na audiência de custódia, o juiz poderá, fundamentadamente,",["relaxar a prisão ilegal, converter em preventiva ou conceder liberdade provisória.","julgar o mérito.","condenar o acusado.","absolver sumariamente.","arquivar o inquérito."],"Art. 310, I a III.")
q(2,"O juiz relaxa a prisão em flagrante quando ela for",["ilegal.","legal, mas o preso estiver doente.","legal e o preso for primário.","feita pela guarda municipal.","feita de madrugada."],"Art. 310, I.")
q(2,"O juiz converte o flagrante em prisão preventiva quando presentes",["os requisitos do art. 312 e forem inadequadas ou insuficientes as medidas cautelares diversas da prisão.","os requisitos do art. 301 apenas.","qualquer dos requisitos do art. 302.","a vontade do delegado.","a confissão do preso."],"Art. 310, II.")
q(2,"Se o juiz verificar, pelo auto, que o agente praticou o fato em estado de necessidade, legítima defesa ou cumprimento de dever legal, poderá conceder",["liberdade provisória, mediante termo de comparecimento obrigatório.","absolvição imediata.","prisão preventiva obrigatória.","prisão temporária.","extinção da punibilidade."],"Art. 310, § 1º.")
q(2,"Se o juiz verificar que o agente é reincidente, ou integra organização criminosa armada ou milícia, ou porta arma de fogo de uso restrito, deverá",["denegar a liberdade provisória, com ou sem medidas cautelares.","conceder liberdade provisória.","arquivar o auto.","remeter ao delegado.","absolvê-lo."],"Art. 310, § 2º.")
q(2,"A autoridade que, sem motivação idônea, der causa à não realização da audiência de custódia responderá",["administrativa, civil e penalmente pela omissão.","apenas administrativamente.","apenas civilmente.","não responde.","apenas penalmente."],"Art. 310, § 3º.")
q(2,"Transcorridas 24 horas após o prazo da audiência de custódia, sua não realização sem motivação idônea",["ensejará a ilegalidade da prisão, a ser relaxada, sem prejuízo de imediata prisão preventiva.","não tem consequência.","extingue o processo.","transforma a prisão em temporária.","obriga a soltura sem possibilidade de nova prisão."],"Art. 310, § 4º.")
q(2,"Entre as circunstâncias que recomendam a conversão do flagrante em preventiva, o art. 310, § 5º, indica",["a prática reiterada de infrações penais e a infração com violência ou grave ameaça.","apenas a confissão.","apenas o primeiro crime.","a idade do preso.","a profissão do preso."],"Art. 310, § 5º, I e II.")
q(2,"No caso de prisão em flagrante por crime com violência ou grave ameaça contra a pessoa, o Ministério Público ou a autoridade policial deverá requerer ao juiz",["a coleta de material biológico para obtenção do perfil genético do custodiado.","a soltura do preso.","o arquivamento do inquérito.","a prisão domiciliar.","a revisão da pena."],"Art. 310-A.")
q(2,"A coleta de material biológico, no art. 310-A, deve ser feita, preferencialmente,",["na própria audiência de custódia ou em 10 dias.","em 30 dias.","somente após a sentença.","em 48 horas.","somente a pedido da defesa."],"Art. 310-A, § 1º.")
q(2,"No texto do assalto, o preso não informou advogado. Nesse caso, cópia integral do auto irá",["à Defensoria Pública.","ao Ministério Público.","ao delegado-geral.","à vítima.","ao juiz da execução."],"Art. 306, § 1º.","cpp2a")
q(2,"No texto do reincidente, o auto foi encaminhado ao juiz no mesmo dia. Isso atende ao prazo de",["24 horas, do art. 306, § 1º.","48 horas.","72 horas.","5 dias.","10 dias."],"Auto ao juiz em até 24 horas.","cpp2b")
q(2,"No texto do reincidente, o preso foi levado à audiência de custódia",["dentro do prazo de 24 horas.","fora do prazo.","apenas depois da denúncia.","com 48 horas de atraso.","sem presença do juiz."],"Marcada para as 20 horas seguintes, dentro das 24 horas do art. 310.","cpp2b")
q(2,"Ao ouvir o condutor, a autoridade colherá, desde logo, sua assinatura e entregará a ele",["cópia do termo e recibo de entrega do preso.","a nota de culpa.","o alvará de soltura.","a cópia da denúncia.","o laudo pericial."],"Art. 304, caput.")
q(2,"Entre as circunstâncias do art. 310, § 5º, que recomendam a prisão preventiva, está ter o agente",["já sido liberado em prévia audiência de custódia por outra infração, salvo se depois absolvido.","sido preso de dia.","sido preso por guarda municipal.","confessado o crime.","apresentado documentos."],"Art. 310, § 5º, III.")
q(2,"Também recomenda a conversão do flagrante em prisão preventiva",["ter havido fuga ou haver perigo de fuga.","ter sido o preso levado pela guarda.","ter o preso emprego fixo.","ter o preso residência fixa.","ter o preso advogado constituído."],"Art. 310, § 5º, V.")
# n=3
q(3,"Assinale a alternativa que descreve o flagrante impróprio.",["O agente é perseguido logo após o crime, em situação que faça presumir ser o autor.","O agente é preso no momento em que comete o crime.","O agente é encontrado dias depois com a arma do crime.","O agente é preso por ordem judicial.","O agente se entrega espontaneamente."],"Art. 302, III.")
q(3,"Assinale a alternativa que descreve o flagrante presumido.",["O agente é encontrado, logo depois, com instrumentos, armas, objetos ou papéis que façam presumir sua autoria.","O agente é perseguido logo após o crime.","O agente é preso cometendo o crime.","O agente é preso depois de uma semana.","O agente comparece à delegacia por conta própria."],"Art. 302, IV.")
q(3,"Sobre a ordem dos atos do art. 304, é correto afirmar que a autoridade ouvirá",["o condutor, depois as testemunhas e, em seguida, interrogará o acusado.","o acusado, o condutor e as testemunhas.","as testemunhas, o condutor e o acusado.","o acusado, as testemunhas e o condutor.","o condutor e o acusado, dispensando as testemunhas."],"Art. 304, caput.")
q(3,"Se não há testemunhas da infração, o auto de prisão em flagrante",["será assinado pelo condutor e por pelo menos duas pessoas que testemunharam a apresentação do preso.","não pode ser lavrado.","deve ser lavrado só pelo condutor.","exige testemunhas da infração.","deve ser anulado pelo juiz."],"Art. 304, § 2º.")
q(3,"Sobre a nota de culpa, é correto afirmar que",["será entregue ao preso, mediante recibo, no prazo de 24 horas, com o motivo da prisão, o nome do condutor e os das testemunhas.","é entregue ao juiz, apenas.","é entregue no prazo de 5 dias.","é desnecessária.","é entregue ao Ministério Público."],"Art. 306, § 2º.")
q(3,"A audiência de custódia deve ser promovida pelo juiz",["no prazo máximo de 24 horas após a realização da prisão, com a presença do acusado, de seu advogado ou defensor e do Ministério Público.","em até 5 dias, com a presença apenas do acusado.","em 48 horas, sem defensor.","em 72 horas, sem promotor.","após a denúncia."],"Art. 310, caput.")
q(3,"Assinale a INCORRETA a respeito do art. 310 do CPP.",["O juiz decide sobre a prisão sem necessidade de fundamentação.","O juiz pode relaxar a prisão ilegal.","O juiz pode converter o flagrante em preventiva.","O juiz pode conceder liberdade provisória.","A decisão deve ser motivada e fundamentada."],"A decisão deve ser fundamentada (art. 310, caput e § 6º).")
q(3,"Segundo o art. 310, § 6º, a decisão sobre a prisão em flagrante",["deve ser motivada e fundamentada, com exame das circunstâncias dos §§ 2º e 5º e dos critérios de periculosidade do art. 312, § 3º.","dispensa fundamentação.","é tomada pelo delegado.","é tomada pelo promotor.","pode ser tomada sem a presença do preso."],"Art. 310, § 6º.")
q(3,"Antes do início da audiência de custódia, constatada pendência de citação em outro processo criminal do acusado, o juiz",["certificará a ocorrência e procederá à citação pessoal do acusado, comunicando o juízo competente.","ignorará a pendência.","arquivará o auto.","devolverá o preso à delegacia.","adiará a audiência."],"Art. 310, § 7º.")
q(3,"Sobre a entrevista prévia entre o preso e o defensor antes da audiência de custódia, é correto afirmar que",["será garantida, de forma reservada e inviolável, presencialmente ou por qualquer meio de comunicação.","é dispensável.","é permitida somente na presença do promotor.","é permitida somente depois da audiência.","é feita apenas por carta."],"Art. 310, § 9º.")
q(3,"Na audiência de custódia por videoconferência, a privacidade do preso é assegurada, devendo ele permanecer",["sozinho na sala durante a oitiva, ressalvada a presença física de seu defensor.","acompanhado de um policial.","acompanhado de um guarda municipal.","acompanhado do delegado.","sempre acompanhado de testemunhas."],"Art. 310, § 10.")
q(3,"No caso de falha no sistema de comunicações atribuível ao tribunal, na audiência de custódia por videoconferência,",["é obrigatória a repetição completa da audiência.","a audiência continua do ponto em que parou.","o preso é solto.","o promotor decide o rumo.","o ato é dispensado."],"Art. 310, § 11.")
q(3,"Em situações excepcionais decorrentes de força maior, a audiência de custódia poderá ser realizada",["presencialmente, por decisão justificada do juiz, vedada a hipótese se o ato for demasiadamente custoso ou trouxer excessivo risco.","por telefone.","por escrito.","sem a presença do preso.","sem a presença do juiz."],"Art. 310, § 13.")
q(3,"A coleta de material biológico, no flagrante por crime hediondo do art. 1º da Lei 8.072/1990, será feita",["por agente público treinado, com respeito à cadeia de custódia.","por qualquer pessoa.","somente por médico particular.","somente por perito particular.","sem necessidade de cadeia de custódia."],"Art. 310-A, § 2º.")
q(3,"Assinale a alternativa correta sobre o art. 310, § 2º.",["O juiz deve denegar a liberdade provisória ao reincidente.","O juiz deve conceder liberdade provisória ao reincidente.","A liberdade provisória é automática para o reincidente.","A regra vale só para crime hediondo.","A regra depende de requerimento do delegado."],"Art. 310, § 2º.")
q(3,"Na audiência de custódia por videoconferência, a defesa técnica e o Ministério Público",["poderão suscitar questões de ordem, sendo facultados todos os mecanismos para sua intervenção.","não podem intervir.","só podem intervir ao final.","dependem de autorização do juiz para cada fala.","só falam por escrito."],"Art. 310, § 8º.")
q(3,"Segundo o art. 310, § 12, todos os estabelecimentos prisionais terão",["salas próprias, com mecanismos de videoconferência estáveis, para as audiências de custódia.","salas de julgamento.","salas de audiência presencial, apenas.","juízes residentes.","defensores permanentes."],"Art. 310, § 12.")
q(3,"No texto do reincidente, ao verificar a reincidência do preso, o juiz",["deve denegar a liberdade provisória, com ou sem medidas cautelares.","deve conceder a liberdade provisória.","deve arquivar o auto.","deve remeter ao promotor.","deve anular a prisão."],"Art. 310, § 2º.","cpp2b")
q(3,"No texto do reincidente, o crime foi praticado com violência contra a pessoa. Essa circunstância",["recomenda a conversão do flagrante em prisão preventiva, nos termos do § 5º.","impede a audiência de custódia.","obriga a soltura.","torna a prisão ilegal.","dispensa a fundamentação."],"Art. 310, § 5º, II.","cpp2b")
q(3,"No texto do assalto, o fato de o preso ter sido perseguido por cinco quadras sem ser perdido de vista",["caracteriza o flagrante impróprio, que exige perseguição logo após o crime.","impede a prisão em flagrante.","exige mandado de prisão.","caracteriza flagrante presumido.","caracteriza prisão preventiva."],"Art. 302, III.","cpp2a")
